#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────
# shellcheck disable=SC2034  # shared wizard palette; not every wizard uses every colour

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Deploys the RWP console to Vercel: v2 into main (which migrates RWP-B), the fund files into Supabase
# Storage, the Vercel project, its environment, and checks. Run from the repo root:  scripts/deploy-vercel.sh
cd "$(git rev-parse --show-toplevel)"
TOTAL_STAGES=11
VERCEL=(npx --yes vercel)
DATA_ROOT="${RWP_DATA_ROOT:-$HOME/Desktop/RWP-funds}"
PIPELINE_MD="${PIPELINE_MD:-$(find "$HOME/Desktop/RWP" -name PIPELINE.md -print -quit 2>/dev/null || true)}"
REF=$(_existing SUPABASE_PROJECT_REF || true)

banner "Deploy the RWP console to Vercel"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
say "This wizard puts the console on Vercel, reading RWP-B (Supabase) and a private Storage bucket."
missing=()
for tool in git gh uv npx; do command -v "$tool" >/dev/null 2>&1 || missing+=("$tool"); done
gh auth status >/dev/null 2>&1 || missing+=("gh login (run: gh auth login)")
[[ -n "$(_existing DATABASE_URL || true)" ]] || missing+=("DATABASE_URL in .env (RWP-B's session pooler URL)")
[[ -n "$REF" ]] || missing+=("SUPABASE_PROJECT_REF in .env (RWP-B's project ref)")
[[ -d "$DATA_ROOT" ]] || missing+=("the data root at $DATA_ROOT (scripts/reorganize_data_root.py builds it)")
if (( ${#missing[@]} )); then
  warn "fix these first, then re-run:"; for m in "${missing[@]}"; do note "  - $m"; done; exit 1
fi
step "RWP-B must be on Supabase Pro (5.7 GB of files) and the Vercel team on Pro (commercial use)."
note "Data root: $DATA_ROOT"
note "PIPELINE.md: ${PIPELINE_MD:-not found; stage 6 will ask}"
confirm "Both plans are Pro, and you are ready to go on?" || exit 1

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Bring v2 into main"
say "Vercel deploys production from main, and v2 lives on feat/v2."
warn "Merging runs the 'Apply migrations to Supabase' job: every v2 table lands in RWP-B. It cannot be undone."
pr=$(gh pr list --base main --head feat/v2 --state open --json number --jq '.[0].number' 2>/dev/null || true)
if [[ -z "$pr" ]] && [[ "$(gh pr list --base main --head feat/v2 --state merged --json number --jq 'length' 2>/dev/null || echo 0)" == "0" ]]; then
  if confirm "Open the pull request feat/v2 → main now?"; then
    gh pr create --base main --head feat/v2 --title "v2: the 2026-10-11 screen decisions, hosted on Vercel" \
      --body "Merges the v2 work (PRs 8 to 22) into main. Merging applies its migrations to RWP-B." >/dev/null
    pr=$(gh pr list --base main --head feat/v2 --state open --json number --jq '.[0].number')
  fi
fi
if [[ -n "$pr" ]]; then
  open_url "$(gh pr view "$pr" --json url --jq .url)"
  step "Wait for CI OK and Migrations OK, then merge with a merge commit (not squash)."
  step "Then watch Actions → Migrations → 'Apply migrations to Supabase' finish green."
  pause "Press Enter once it is merged and the migrations job has passed."
fi
[[ "$(gh pr list --base main --head feat/v2 --state merged --json number --jq 'length')" != "0" ]] \
  || { warn "feat/v2 is not merged into main yet; re-run when it is."; exit 1; }
git fetch -q origin main
say "v2 is on main."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: the service key the console uses for Storage"
open_url "https://supabase.com/dashboard/project/$REF/settings/api-keys"
step "In Project Settings → API Keys, copy the service_role key (a secret key: it bypasses row-level security)."
note "If the page has moved, it is under Project Settings in RWP-B. The key stays on the server, never in the browser."
SUPABASE_URL="https://$REF.supabase.co"
ask_secret SUPABASE_SERVICE_ROLE_KEY "Paste the service_role key:"
write_env SUPABASE_URL "$SUPABASE_URL"
write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase: let Storage take the largest files"
largest=$(find "$DATA_ROOT" -type f -not -path '*/_index/*' -printf '%s\n' | sort -n | tail -1)
say "The largest fund file is $(( largest / 1000000 )) MB; Storage's default limit is lower."
open_url "https://supabase.com/dashboard/project/$REF/storage/buckets"
step "Open Storage settings and set the Global file size limit to at least 1 GB, then save."
note "Pro allows up to 500 GB. If the setting is elsewhere, search the dashboard for 'file size limit'."
pause "Press Enter once the limit is saved."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Upload the fund files"
say "Files go to the private bucket fund-files; rooms, page text and catalogs go to RWP-B."
uv run --frozen python scripts/upload_data_root.py "$DATA_ROOT"
if confirm "Upload now? (5.7 GB the first time; re-runs send only changes)"; then
  uv run --frozen python scripts/upload_data_root.py "$DATA_ROOT" --yes
  pause "Upload finished. Press Enter to continue."
else
  SKIPPED+=("upload: uv run python scripts/upload_data_root.py \"$DATA_ROOT\" --yes")
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Import the pipeline statuses, once"
say "The console keeps statuses in RWP-B; this copies PIPELINE.md's statuses and owners in a single time."
[[ -f "$PIPELINE_MD" ]] || ask PIPELINE_MD "Path to PIPELINE.md (from the Drive download):"
if [[ -f "$PIPELINE_MD" ]]; then
  uv run --frozen python scripts/import_pipeline_md.py "$PIPELINE_MD" "$DATA_ROOT" | tail -3
  if confirm "Import these statuses into RWP-B?"; then
    uv run --frozen python scripts/import_pipeline_md.py "$PIPELINE_MD" "$DATA_ROOT" --yes | tail -1
  else
    SKIPPED+=("statuses: uv run python scripts/import_pipeline_md.py \"$PIPELINE_MD\" \"$DATA_ROOT\" --yes")
  fi
else
  SKIPPED+=("statuses: no PIPELINE.md found")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "The console password"
say "Everyone signs in to the deployed console with one shared password (SITE_PASSWORD)."
note "It is not written to .env, so your local console stays open. Keep it in your password manager."
SITE_PASSWORD=""
while [[ ${#SITE_PASSWORD} -lt 12 ]]; do
  read -rsp "  Choose the password (12+ characters): " SITE_PASSWORD; printf '\n'
done
set_secret E2E_SITE_PASSWORD "$SITE_PASSWORD"   # the preview smoke recipes sign in with it

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Vercel: create the project and link this folder"
open_url "https://vercel.com/new"
step "Import the GitHub repository bsim0927/RWP-console into your Pro team."
step "Framework Preset: Other. Root Directory: ./ . Leave the build settings as they are."
step "Deploy. This first deployment will fail or show errors: it has no environment yet. That is expected."
pause "Press Enter once the project exists."
"${VERCEL[@]}" whoami >/dev/null 2>&1 || "${VERCEL[@]}" login
say "Link this folder to the project (choose your team and the project you just created):"
"${VERCEL[@]}" link
grep -qxF ".vercel" .gitignore || { printf '.vercel\n' >> .gitignore; note "added .vercel to .gitignore"; }

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Vercel: environment variables"
say "Setting the variables for Production and Preview (values from .env, plus the password)."
vercel_env() {
  local name="$1" value="$2" target
  for target in production preview; do
    "${VERCEL[@]}" env rm "$name" "$target" --yes >/dev/null 2>&1 || true
    if printf '%s' "$value" | "${VERCEL[@]}" env add "$name" "$target" >/dev/null 2>&1; then
      printf '  %s✓ set%s %s (%s)\n' "$GREEN" "$RESET" "$name" "$target"
    else
      SKIPPED+=("Vercel env $name ($target)"); warn "could not set $name for $target"
    fi
  done
}
vercel_env DATABASE_URL "$(_existing DATABASE_URL)"
vercel_env ANTHROPIC_API_KEY "$(_existing ANTHROPIC_API_KEY)"
vercel_env JEV_API_KEY "$(_existing JEV_API_KEY)"
vercel_env SUPABASE_URL "$SUPABASE_URL"
vercel_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
vercel_env SITE_PASSWORD "$SITE_PASSWORD"
vercel_env RWP_DATA_SOURCE "hosted"
note "Preview deployments read RWP-B too: a PR whose migrations are not on main yet may error there."
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Deploy to production and check it"
"${VERCEL[@]}" deploy --prod | tee /dev/stderr | tail -n1 > .vercel/last-url || true
URL=$(tr -d '[:space:]' < .vercel/last-url)
read -rp "  Production URL [Enter keeps $URL]: " typed || true
URL="${typed:-$URL}"
code=$(curl -s -o /dev/null -w '%{http_code}' "$URL/api/meta" || true)
if [[ "$code" == "401" ]]; then
  say "✓ the API refuses callers without a session"
else
  warn "expected 401 from $URL/api/meta, got $code"
fi
say "Running the smoke recipes against it, signed in:"
if E2E_BASE_URL="$URL" E2E_SITE_PASSWORD="$SITE_PASSWORD" npx playwright test --grep @smoke --project=desktop; then
  say "✓ smoke recipes pass"
else
  SKIPPED+=("smoke recipes failed against $URL: see e2e/.report"); warn "smoke recipes failed"
fi
open_url "$URL"
step "Sign in, open a fund, then a cited document: the PDF should open (served from Storage)."
step "Optional: run one screen on a fund to confirm the model keys work in production."
pause "Press Enter when you have checked it."

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Smoke-test every preview deployment in CI"
say "The Preview smoke workflow runs the @smoke recipes on each Vercel preview."
step "In the Vercel project: Settings → Deployment Protection → Protection Bypass for Automation."
step "Create the secret and copy it."
open_url "https://vercel.com/dashboard"
ask_secret VERCEL_AUTOMATION_BYPASS_SECRET "Paste the bypass secret (Enter to skip if previews are not protected):"
if [[ -n "${VERCEL_AUTOMATION_BYPASS_SECRET:-}" ]]; then
  set_secret VERCEL_AUTOMATION_BYPASS_SECRET "$VERCEL_AUTOMATION_BYPASS_SECRET"
fi
say "Production: $URL"

finish
